sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.wrm-cap-summary {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-card);
  padding: 16px 18px;
  margin-bottom: 12px;
}
.wrm-cap-summary .line { font-size: 16px; color: var(--ink); line-height: 1.55; }
.wrm-cap-summary .line strong { font-weight: 500; }
.wrm-cap-summary .sub { font-size: 13px; color: var(--ink-3); margin-top: 5px; }

.wrm-cap-rows {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-card);
  padding: 8px 18px 14px;
}

.wrm-cap-rows .row {
  display: flex; align-items: center; gap: 12px;
  padding: 8px 0;
  border-top: 1px solid var(--line);
}
.wrm-cap-rows .row:first-child { border-top: 0; }

.wrm-cap-rows .nm { width: 130px; flex: none; font-size: 12px; color: var(--ink); }
.wrm-cap-rows .ct { flex: none; font-size: 11px; color: var(--ink-3); }

.wrm-cap-rows .dots { display: flex; gap: 5px; flex: 1; flex-wrap: wrap; }
.wrm-cap-rows .dots i {
  width: 11px; height: 11px; border-radius: 50%; display: block;
}
.wrm-cap-rows .dots i.free   { background: var(--free-fg); opacity: .55; }
.wrm-cap-rows .dots i.booked { background: var(--held-fg); opacity: .45; }
.wrm-cap-rows .dots i.maint  { background: var(--out-fg);  opacity: .45; }

.wrm-cap-rows .key {
  display: flex; gap: 16px;
  margin-top: 10px; padding-top: 11px;
  border-top: 1px solid var(--line);
  font-size: 11px; color: var(--ink-3);
}
.wrm-cap-rows .key i {
  display: inline-block; width: 9px; height: 9px;
  border-radius: 50%; margin-right: 5px;
}
.wrm-cap-rows .key i.free   { background: var(--free-fg); opacity: .55; }
.wrm-cap-rows .key i.booked { background: var(--held-fg); opacity: .45; }
.wrm-cap-rows .key i.maint  { background: var(--out-fg);  opacity: .45; }

sp_widget.script:
(function() {

  var HOLDING = 'pending_check_in,checked_in';
  var todayYmd = new GlideDateTime().getDisplayValue().split(' ')[0];

  // Which workspaces are held at some point today.
  var heldToday = {};
  var res = new GlideRecord('x_1903615_worksp_0_reservation_tracker');
  res.addQuery('reservation_status', 'IN', HOLDING);
  res.query();
  while (res.next()) {
    var sDisp = res.getDisplayValue('work_start');
    var eDisp = res.getDisplayValue('work_end');
    if (!sDisp || !eDisp) continue;

    var sYmd = sDisp.split(' ')[0];
    var eYmd = eDisp.split(' ')[0];

    if (sYmd <= todayYmd && eYmd >= todayYmd) {
      heldToday[res.getValue('workspace')] = true;
    }
  }

  // Grouped by workspace type — a real field, rather than a
  // building name parsed out of the location label.
  var types = {};
  var maintCount = 0;

  var gr = new GlideRecord('x_1903615_worksp_0_workspace_options');
  gr.addQuery('status', '!=', 'decommissioned');
  gr.orderBy('workspace_name');
  gr.query();

  while (gr.next()) {
    var label = gr.getDisplayValue('workspace_type') || 'Other';

    if (!types[label]) {
      types[label] = { name: label, total: 0, free: 0, dots: [] };
    }

    var state;
    if (gr.getValue('status') === 'under_maintenance') {
      state = 'maint';
      maintCount++;
    } else if (heldToday[gr.getUniqueValue()]) {
      state = 'booked';
    } else {
      state = 'free';
      types[label].free++;
    }

    types[label].total++;
    types[label].dots.push(state);
  }

  // Free dots first, then booked, then maintenance — so the row
  // reads as a bar rather than a scatter.
  var ORDER = { free: 0, booked: 1, maint: 2 };

  data.types = [];
  var best = null;
  var fullTypes = [];

  for (var k in types) {
    var row = types[k];
    row.dots.sort(function(a, c) { return ORDER[a] - ORDER[c]; });
    data.types.push(row);

    if (!best || row.free > best.free) best = row;
    if (row.free === 0) fullTypes.push(row.name);
  }

  data.types.sort(function(a, c) { return c.free - a.free; });

  // --- the summary sentence ---
  data.headline = '';
  if (best && best.free > 0) {
    data.headline      = best.name;
    data.headlineFree  = best.free;
    data.headlineTotal = best.total;
  }

  var bits = [];
  if (fullTypes.length === 1) {
    bits.push('No ' + fullTypes[0].toLowerCase() + ' is free today.');
  } else if (fullTypes.length > 1) {
    bits.push(fullTypes.length + ' types are fully booked.');
  }
  if (maintCount === 1) {
    bits.push('One space is out for maintenance.');
  } else if (maintCount > 1) {
    bits.push(maintCount + ' spaces are out for maintenance.');
  }
  data.detail = bits.join(' ');

})();
